#include <stdio.h>

void add_ten(int *number)
{
    *number = *number + 10;
}

int main(void)
{
    int score = 5;
    int *p = &score;      /* p holds the address of score */

    printf("score = %d, address = %p\n", score, (void *)p);
    add_ten(&score);      /* the function changes the real variable */
    printf("score = %d\n", score);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int count = 3;
    int *marks = malloc(count * sizeof(int));

    if (marks == NULL)
    {
        printf("Not enough memory\n");
        return 1;
    }

    for (int i = 0; i < count; i++)
        marks[i] = (i + 1) * 10;

    printf("second mark = %d\n", marks[1]);
    free(marks);          /* always give the memory back */
    return 0;
}

